# Apache-2.0. Inert economics-only candidate materializer. Does not edit active inputs.
import copy, datetime, hashlib, json, pathlib

BASE = pathlib.Path(__file__).resolve().parent
ROOT = BASE.parents[6]
NOW = datetime.datetime.now(datetime.timezone.utc).isoformat()
def read(path): return json.loads((ROOT / path).read_text())
def write(name, value):
    with (BASE / name).open('x') as f:
        f.write(json.dumps(value, ensure_ascii=False, indent=2) + '\n')
def digest(path): return 'sha256:' + hashlib.sha256(path.read_bytes()).hexdigest()
def case(key, task_de, task_en, expected_de, expected_en, focus_de, focus_en):
    return dict(id=key, taskDemandDe=task_de, taskDemandEn=task_en,
                expectedPerformanceDe=expected_de, expectedPerformanceEn=expected_en,
                understandingFocusDe=focus_de, understandingFocusEn=focus_en)

# Each explicit content option is an authored selection from an optional WWG profile.
