SPECS = [
dict(prefix='8964ef4b', title='Baustellen- und Inselfertigung vergleichen', title_en='Compare fixed-position and cellular production',
 description='Die lernende Person kann Baustellen- und Inselfertigung anhand vorgegebener Produktionsfälle hinsichtlich Arbeitsorganisation und Materialfluss vergleichen und ihre Eignung für das jeweilige Produkt begründen.',
 description_en='The learner can compare fixed-position and cellular production in supplied production cases with regard to work organisation and material flow and explain their suitability for the product.',
 requires=['aa9db8f6-c81e-5247-8f84-5f2b968ab2c4'], section='WR8 4.2', content='weitere Fertigungsverfahren, z. B. Baustellenfertigung, Inselfertigung', year=8,
 boundary='Eine zusammenhängende Fertigungsverfahrensanalyse; keine allgemeine Marketing-, vollständige Produktionssystem- oder universelle Kostenoptimierungskompetenz.',
 prereq_reason='Die Kernprozessanalyse trägt den Produktionsvergleich. Ein vollständiges Marketingkonzept ist für die vorgegebenen Fertigungsfälle keine notwendige Vorleistung.',
 essential_de='Bei Baustellenfertigung bleibt das Produkt am Ort, während Menschen, Werkzeuge und Material zu ihm kommen. Eine Fertigungsinsel bündelt mehrere Arbeitsschritte und Ressourcen für eine Produktfamilie; sie ist keine kleine Fließlinie per Definition. Eignung hängt von Transportierbarkeit, Prozess und Koordination ab, nicht von einer garantierten Kostensenkung.',
 essential_en='In fixed-position production the product stays in place while workers, tools and materials come to it. A production cell groups several operations and resources for a product family; it is not necessarily a small assembly line. Suitability depends on transportability, process and coordination rather than guaranteed cost savings.',
 performance_de='Die Person ordnet die vorgegebenen Fälle zu, beschreibt Personal- und Materialbewegungen und begründet mit den Produkt-/Prozessbedingungen die Verfahrenseignung und eine Grenze.',
 performance_en='The learner classifies the supplied cases, describes movements of workers and materials and uses product/process conditions to explain suitability and a limitation.',
 archetype='concept', axes=[('product-movement','Ortsfestes großes Produkt gegenüber beweglichen Produktfamilien.','A large fixed product versus movable product families.'),('coordination','Zentrale Baustellenkoordination gegenüber gebündelten Arbeitsschritten einer Insel.','Site coordination versus grouped operations within a cell.')],
 cases=[case('turbine-and-bicycle-cell','Ein fiktives großes Windrad wird am Fundament montiert; Spezialteams und Bauteile kommen nacheinander zur Anlage. In einem anderen Betrieb fertigt ein kleines Team an einer mit mehreren Werkzeugen ausgestatteten Insel verschiedene Fahrradmodelle durch mehrere Montageschritte. Vergleiche Arbeitsorganisation und Materialfluss, ordne die Verfahren zu und begründe die Eignung.','A fictional large wind turbine is assembled on its foundation; specialist teams and parts come to the turbine in sequence. At another firm, a small team uses a multi-tool cell to perform several assembly operations on different bicycle models. Compare work organisation and material flow, classify the methods and explain suitability.','Windrad: Baustellenfertigung wegen ortsfestem schwerem Produkt, Material/Teams bewegen sich zum Produkt. Fahrräder: Inselfertigung wegen gebündelten Arbeitsschritten für eine Produktfamilie; Abstimmung und flexible Qualifikation bleiben nötig. Aus der Form allein folgt keine garantierte Geschwindigkeit oder Kostensenkung.','Turbine: fixed-position production because the large product stays in place and parts/teams move to it. Bicycles: cellular production with grouped operations for a product family; coordination and flexible skills remain necessary. The method alone guarantees neither speed nor lower cost.','Organisationsform am tatsächlichen Ablauf statt am Branchenetikett erkennen.','Identify organisation from the actual process rather than an industry label.'),
 case('modular-furniture-vs-installed-kitchen','Eine fiktive Werkstatt bündelt Zuschnitt, Bohren und Montage kleiner modularer Schränke in einer Teaminsel. Eine individuell eingepasste schwere Einbauküche wird in der Wohnung des Kunden fertig montiert; Werkzeuge und Teams kommen dorthin. Begründe die unterschiedlichen Material-/Personalwege und nenne je einen Koordinationsbedarf; gleiche Qualität und Kosten sind nicht vorgegeben.','A fictional workshop groups cutting, drilling and assembly of small modular cupboards in a team cell. A heavy fitted kitchen is completed at the customer’s home, where tools and teams arrive. Explain the different movements of materials/workers and a coordination need for each; equal quality and costs are not stipulated.','Insel: mehrere Schritte am beweglichen Modul mit abgestimmtem Team; Baustelle: ortsfeste kundenspezifische Endmontage und externe Termin-/Lieferkoordination. Ein Möbelbetrieb kann beide Verfahren nutzen. Eine pauschale Rangfolge ohne Daten ist unzulässig.','Cell: several operations on movable modules with a coordinated team; site: fixed customer-specific final assembly and coordination of deliveries/schedules. One furniture firm can use both methods. No universal ranking follows without data.','Frischer Fall mit derselben Branche, aber verschiedenen tatsächlichen Abläufen.','A fresh case within one industry with different actual processes.')]),
dict(prefix='71319337',title='Beschäftigung Minderjähriger anhand von Schutzregeln prüfen',title_en='Assess employment of minors using protective rules',
 description='Die lernende Person kann in vorgegebenen Beschäftigungsfällen Minderjähriger anhand bereitgestellter aktueller Normen Alter, Schulpflicht, Arbeitszeit und Schutzbedingungen prüfen und die Zulässigkeit im Umfang dieser Kriterien begründet einordnen.',
 description_en='The learner can assess age, compulsory schooling, working time and protective conditions in supplied employment cases involving minors using provided current legal provisions and give a reasoned assessment of permissibility within those criteria.',
 requires=['dae93971-726c-56e5-8044-19dbd40febf7'],section='WR8 4.3',content='rechtliche Grundlagen für die Beschäftigung von Minderjährigen',year=8,
 boundary='Dieselbe materialgestützte Schutzregelprüfung; keine vollständige Beratung, Strafrechts-/Urheberrechtsprüfung oder allgemeine Freigabe jeder Tätigkeit.',
 prereq_reason='Strukturierte Norm-/Fallsubsumtion ist der passende Methodenanker. Widerrechtlichkeitsfolgen, Internet- und Urheberrecht sind für beide Beschäftigungsfälle nicht notwendige Vorleistungen.',
 essential_de='Jugendarbeitsschutz unterscheidet nach Alter und Vollzeitschulpflicht. Für vollzeitschulpflichtige Jugendliche gelten grundsätzlich die Kinderregeln; die gesetzliche Ferienausnahme ist zeitlich begrenzt. Arbeitszeit und erlaubte Uhrzeiten allein ersetzen nicht die übrigen Schutzbedingungen. Jede Aussage bleibt an die bereitgestellten datierten Normen gebunden.',
 essential_en='Youth employment protection distinguishes age and full-time compulsory schooling. Adolescents subject to full-time compulsory schooling are generally covered by the child rules; the statutory school-holiday exception is time-limited. Daily hours and allowed times do not replace other safeguards. Each conclusion is tied to the supplied dated provisions.',
 performance_de='Die Person prüft die entscheidenden Tatbestandsmerkmale und Grenzen aus dem Material, unterscheidet eine zulässige Modellvariante von einer belegten Verletzung und kennzeichnet nicht geprüfte Bedingungen.',
 performance_en='The learner applies the relevant conditions and limits in the material, distinguishes a permissible model variant from an evidenced violation and identifies conditions not assessed.',
 archetype='procedure',axes=[('school-status','Vollzeitschulpflicht gegenüber nicht vollzeitschulpflichtiger Jugendlicher.','Full-time compulsory schooling versus an adolescent no longer subject to it.'),('protection-limit','Arbeitszeit-/Uhrzeitgrenze gegenüber Dauer der Ferienbeschäftigung.','Working-time/time-of-day limits versus duration of holiday work.')],
 cases=[case('sixteen-regular-employment-times','Ein fiktiver 16-Jähriger ist nicht mehr vollzeitschulpflichtig. Eine nicht von branchenbezogenen Sonderregeln erfasste Tätigkeit dauert Montag bis Freitag je acht Arbeitsstunden innerhalb6–20Uhr. Vergleiche einen Entwurf mit neun täglichen Arbeitsstunden und einen Entwurf mit Arbeitsende21Uhr. Material: datierte §§2,8,14,22 JArbSchG; Ausnahmen nach§8 greifen ausdrücklich nicht. Pausen, Ruhetage, gegebenenfalls Untersuchungsbescheinigung und die übrigen Schutzanforderungen sind im Material als erfüllt angegeben. Prüfe nur die geänderten Kriterien.','A fictional sixteen-year-old is no longer subject to full-time compulsory schooling. Work outside sectors with special exceptions takes eight working hours a day Monday to Friday within6a.m.–8p.m. Compare variants with nine daily working hours and a9p.m. finish. Supplied: dated JArbSchG sections2,8,14,22; section8 exceptions expressly do not apply. Breaks, rest days, any required examination certificate and other safeguards are stated as satisfied. Assess only the changed criteria.','Die Person ordnet den Jugendlichen ein und prüft8Stunden/40Wochenstunden sowie6–20Uhr unter den gegebenen Bedingungen. NeunStunden verletzen hier die ausdrücklich nicht erweiterte Grenze;21Uhr ist ohne Branchenausnahme nicht zulässig. Die Ausgangsvariante besteht die begrenzte Kriterienprüfung, keine allgemeine Freigabe aller realen Beschäftigungsbedingungen.','The learner classifies the adolescent and checks eight hours/forty weekly hours and6a.m.–8p.m. under the stated conditions. Nine hours exceed the unextended limit here;9p.m. is impermissible without the sector exception. The initial variant passes the bounded criteria check, not a complete approval of real employment.','Datierte gesetzliche Bedingungen subsumieren, keine bloße Altersregel auswendig reproduzieren.','Apply dated statutory conditions rather than repeat an age rule.'),
 case('fulltime-school-holiday-duration','Eine andere fiktive 16-Jährige ist noch vollzeitschulpflichtig. Eine Ferienbeschäftigung soll im selben Kalenderjahr vier oder fünf Wochen dauern; bisher gab es keine Ferienarbeit. Datierte §§2(3),5(4) JArbSchG und die dort verwiesenen Jugend-Schutzvorschriften liegen vor; Tätigkeit, Zeiten, Pausen und weitere Schutzbedingungen sind im Material identisch als erfüllt angegeben. Erkläre, weshalb16Jahre allein die Beschäftigung nicht freigeben, und vergleiche beide Dauern.','A different fictional sixteen-year-old still attends full-time compulsory schooling. A holiday job is planned for four or five weeks in the same calendar year; there has been no earlier holiday work. Dated JArbSchG sections2(3),5(4) and the referenced adolescent safeguards are supplied; activity, hours, breaks and other protections are identically stated as satisfied. Explain why age sixteen alone does not approve the job and compare both durations.','Die Person wendet wegen Vollzeitschulpflicht grundsätzlich die Kinderregeln an und prüft die begrenzte Ferienausnahme: höchstens vier Wochen im Kalenderjahr. Vier Wochen können bei den gegebenen übrigen erfüllten Bedingungen erfasst sein, fünf nicht. Andere Kinderarbeitsausnahmen werden weder pauschal ausgeschlossen noch ohne Tatbestandsprüfung ergänzt.','Because full-time compulsory schooling applies, the learner starts from the child rules and checks the limited holiday exception: at most four weeks in a calendar year. Four weeks can fall within it when the other stated safeguards are met; five cannot. Other child-work exceptions are neither universally denied nor added without their conditions.','Schulstatus und gesetzliche Ausnahme verändern die Prüfung trotz gleichen Alters.','School status and a statutory exception change the assessment despite the same age.')]),
dict(prefix='f90e4741',title='Innovationswirkungen auf Wirtschaft und Gesellschaft analysieren',title_en='Analyse effects of innovation on the economy and society',
 description='Die lernende Person kann an vorgegebenen Innovationsfällen Wirkungswege vom Unternehmen zu Wirtschaft und Gesellschaft analysieren und Bedingungen sowie mögliche Zielkonflikte dieser Wirkungen erläutern.',description_en='The learner can analyse pathways from business innovation to effects on the economy and society in supplied cases and explain conditions and possible trade-offs.',
 requires=['e90586d8-8e0a-5355-87d0-4ecd90dbe021'],section='WR10 5.1',content='Einfluss von Innovationen auf Gesamtwirtschaft und Gesellschaft',year=10,
 boundary='Eine Innovationswirkungsanalyse über betroffene Gruppen; keine vollständige Unternehmerpersönlichkeit, Statistikmanipulations- oder allgemeine politische Einflusskompetenz.',prereq_reason='Stakeholder-Betrachtung trägt die Wirkungsanalyse. Die bisher zusätzlich direkt geforderte Geschäftsmodellkompetenz ist bereits Voraussetzung dieses beibehaltenen Vorgängers; die transitive Grundlage wird nicht entfernt.',
 essential_de='Innovation kann Verfahren, Produkte und Organisationsformen verändern. Direkte Kosten-/Leistungsänderungen eines Betriebs sind von gesamtwirtschaftlichen Produktivitäts-, Beschäftigungs-, Verteilungs- und Umweltwirkungen zu trennen. Übertragung hängt etwa von Nachfrage, Qualifizierung und Verbreitung ab; Technik garantiert weder Wohlstand noch Arbeitsplatzverlust.',essential_en='Innovation can change processes, products and organisation. Direct cost/performance changes at a firm differ from aggregate productivity, employment, distribution and environmental effects. Transmission depends on demand, training and diffusion; technology guarantees neither prosperity nor job loss.',
 performance_de='Die Person entwickelt anhand von Fallbelegen eine nachvollziehbare Wirkungsfolge für Unternehmen und andere Betroffene, benennt Bedingungen und trennt belegte Änderung, mögliche Folge und offenen Zielkonflikt.',performance_en='Using case evidence, the learner develops a coherent pathway affecting the firm and other groups, states conditions and separates evidenced changes, possible effects and unresolved trade-offs.',archetype='concept',axes=[('innovation-type','Produktionsverfahren gegenüber neuer gemeinsamer Nutzung.','A production process versus a new shared-use service.'),('transmission','Direkte Betriebswirkung gegenüber Nachfrage-, Qualifikations- und Verteilungsfolgen.','Direct firm effects versus demand, skills and distribution effects.')],
 cases=[case('predictive-maintenance','Ein fiktiver Betrieb nutzt Sensoren für vorausschauende Wartung: Ausfallstunden sinken im Probelauf von100auf70, Schulung verursacht zusätzliche Kosten. Absatz und Personalentwicklung sind unbekannt. Analysiere mögliche Wirkungswege zu Kunden, Beschäftigten und gesamtwirtschaftlicher Produktion, ohne den Probelauf zum sicheren allgemeinen Erfolgsbeleg zu machen.','A fictional firm uses sensors for predictive maintenance: downtime falls from100to70hours in a trial and training adds costs. Sales and staffing changes are unknown. Analyse possible pathways to customers, workers and aggregate production without treating the trial as proof of universal success.','30%weniger Ausfallstunden ist ein direkter Befund. Mehr mögliche Kapazität kann bei passender Nachfrage und Qualifikation Produktion/Produktivität unterstützen, aber weder tatsächlicher Mehrabsatz noch Arbeitsplatzabbau ist bewiesen. Schulungsbelastung, neue Tätigkeiten und Verteilung der Vorteile gehören zu den Bedingungen.','A30% fall in downtime is a direct observation. Additional available capacity can support production/productivity with suitable demand and skills, but neither higher actual sales nor job cuts are established. Training costs, new tasks and distribution of gains are conditions.','Betriebsbefund, Übertragung und unsichere Gesamtwirkung unterscheiden.','Distinguish a firm observation, transmission and uncertain aggregate effects.'),
 case('shared-tool-service','Eine zweite fiktive Innovation ermöglicht gemeinsames Ausleihen von Werkzeugen über einen Dienst. Haushalte benötigen weniger eigene Geräte, der Dienst braucht Reparaturpersonal; Ersatzkäufe und Transporte sind nicht gemessen. Analysiere Wirkungsketten auf Hersteller, Haushalte, Beschäftigung und Umwelt und benenne, welche Daten für weitergehende Aussagen nötig sind.','A second fictional innovation enables shared tool borrowing through a service. Households need fewer individually owned tools and the service requires repair staff; replacement purchases and transport are unmeasured. Analyse effects on manufacturers, households, employment and the environment and identify the evidence needed for stronger conclusions.','Die Person unterscheidet Zugangs-/Nutzungsvorteil, mögliche Verschiebung von Neuproduktion zu Dienstleistungen sowie offene Netto-Beschäftigungs-/Umwelteffekte. Haltbarkeit, tatsächliche Nutzungen, Transport und verdrängte Käufe sind Bedingungen. Nicht jede Innovation ist ökologisch überlegen.','The learner distinguishes access/use benefits, possible shifts from new production to services and unresolved net employment/environmental effects. Durability, actual use, transport and displaced purchases are conditions. Innovation is not automatically environmentally superior.','Andere Innovationsform mit Nachfrageverschiebung statt identischem Effizienzschock.','A different innovation with demand shifts rather than the same efficiency shock.')]),
dict(prefix='51203e8f',title='Zivilprozess und Strafverfahren unterscheiden',title_en='Distinguish civil and criminal proceedings',description='Die lernende Person kann Zivilprozess und Strafverfahren anhand vorgegebener Fälle nach Zweck, beteiligten Rollen und grundlegenden Verfahrensschritten unterscheiden und mögliche Ergebnisse von bloßen Vorwürfen abgrenzen.',description_en='The learner can distinguish civil and criminal proceedings in supplied cases by purpose, participants and basic procedural steps and distinguish possible outcomes from allegations.',requires=['dae93971-726c-56e5-8044-19dbd40febf7'],section='WR10 5.2',content='Strafverfahren, Zivilprozess, ggf. Besuch einer Gerichtsverhandlung',year=10,boundary='Eine Verfahrenszweck-/Rollenanalyse, kein Pflichtgerichtsbesuch und keine vollständige Anspruchs-/Straftatprüfung.',prereq_reason='Strukturierte Fall-/Regelunterscheidung bleibt. Jugendkriminalitäts-Tatbestände sind keine universelle Vorleistung für zivilrechtliche oder erwachsene Verfahrensfälle.',essential_de='Ein Zivilprozess behandelt private Ansprüche, ein Strafverfahren einen staatlichen Strafvorwurf. Dasselbe Ereignis kann beide berühren. Ermittlungen, Klage oder Anklage sind keine Verurteilung; Verfahrensrollen, Prüfung und mögliche Ergebnisse müssen getrennt werden.',essential_en='Civil proceedings concern private claims; criminal proceedings concern a state allegation of an offence. One event can involve both. Investigation, a civil claim or an indictment is not a conviction; roles, assessment and possible outcomes must be separated.',performance_de='Die Person ordnet getrennte Verfahrensziele und Rollen zu, erläutert am Material grundlegende Schritte und differenziert begrenzte Ausgänge ohne aus einem Verdacht Schuld abzuleiten.',performance_en='The learner identifies separate procedural purposes and roles, explains basic steps using the supplied material and distinguishes possible outcomes without inferring guilt from suspicion.',archetype='procedure',axes=[('procedure-purpose','Privater Ersatzanspruch gegenüber staatlichem Strafvorwurf.','A private remedy claim versus a state criminal allegation.'),('evidence-stage','Klage/Ermittlung, Prüfung und mögliche unterschiedliche Ergebnisse.','Claim/investigation, assessment and possibly different outcomes.')],cases=[case('damaged-bike-two-proceedings','Nach einer fiktiven Beschädigung eines Fahrrads verlangt die Eigentümerin Ersatz; die Polizei untersucht einen Verdacht vorsätzlicher Sachbeschädigung. Material: grundlegender Ablauf des Zivilprozesses samt§253ZPO sowie Ermittlungen nach§§160,170StPO. Vergleiche Zwecke, Parteien/Rollen und mögliche Schritte; die Tat ist nicht bewiesen.','After fictional damage to a bicycle, the owner claims compensation and police investigate suspected intentional criminal damage. Material provides the basic civil process with ZPOsection253 and investigation under StPOsections160,170. Compare purposes, parties/roles and possible steps; the act is unproven.','Zivil: Anspruch zwischen Klägerin/Beklagtem, gerichtliche Prüfung und gegebenenfalls Leistungsurteil. Straf: Staatsanwaltschaft untersucht auch entlastende Umstände; hinreichender Anlass kann zur Anklage führen, fehlender zur Einstellung. Beides kann parallel laufen, aber Vorwurf/Klage bedeuten weder erfüllten Anspruch noch Verurteilung.','Civil: claim between claimant/defendant, judicial assessment and possibly an order for performance. Criminal: prosecutors examine exculpatory circumstances too; sufficient grounds may lead to charges, otherwise termination. Both can run in parallel, but an allegation/claim is neither an established civil entitlement nor a conviction.','Zwei Verfahrenszwecke am selben unbewiesenen Ereignis.','Two procedural purposes arising from the same unproven event.'),case('wage-claim-and-theft-suspicion','In einem neuen fiktiven Fall klagt eine Beschäftigte vor dem Arbeitsgericht auf ausstehenden Lohn; unabhängig davon wird gegen eine andere Person wegen Diebstahlsverdachts ermittelt. Material beschreibt die jeweiligen Zwecke und lässt Beweise/Entscheidung offen. Unterscheide die Verfahren, Rollen und zulässigen Aussagen zum Ergebnis.','In a fresh fictional case, a worker claims unpaid wages in a labour court, while a different person is investigated for suspected theft. Material describes each purpose and leaves evidence/outcomes open. Distinguish proceedings, roles and permissible conclusions about results.','Die Lohnklage behandelt einen privatrechtlichen Anspruch trotz spezialisiertem Arbeitsgericht; Ermittlung behandelt einen Strafvorwurf. Zahlungsurteil/Vergleich und Einstellung/weitere Strafverfahrensschritte sind unterschiedliche mögliche Ergebnisse. Weder der Gerichtszweig noch ein Verdacht beweist Schuld oder sichere Zahlung.','The wage claim concerns a private-law entitlement despite the specialised labour court; investigation concerns a criminal allegation. A payment judgment/settlement and termination/further criminal steps are distinct possible outcomes. Neither the court branch nor suspicion proves guilt or guaranteed payment.','Spezialisierter Zivilrechtsstreit ändert den Verfahrenszweck nicht.','A specialised private-law dispute does not change the procedural purpose.')]),
dict(prefix='f7c051f4',title='Gemeinwohlökonomie und Soziale Marktwirtschaft vergleichen',title_en='Compare an Economy for the Common Good proposal with the social market economy',description='Die lernende Person kann eine bereitgestellte Gemeinwohlökonomie-Konzeption mit der Sozialen Marktwirtschaft anhand von Zielsetzung, Eigentum und Koordination vergleichen und Aussagen jeweils an die beschriebenen Regeln binden.',description_en='The learner can compare a supplied Economy for the Common Good proposal with the social market economy by objectives, property and coordination and tie conclusions to the described rules.',requires=['1da809f7-ef85-5a2d-babf-b7639e605653'],section='WR11 7.1',content='alternative Wirtschaftsordnungen, z. B. Gemeinwohlökonomie',year=11,boundary='Ein materialgebundener Ordnungsvergleich; keine vorgeschriebene Zustimmung, Länder-Vollanalyse oder behauptete geltende GWÖ-Gesetzespflicht.',prereq_reason='Die Einordnung Sozialer Marktwirtschaft ist das konkrete Vergleichsfundament. Ein zuvor vollständig gebildetes Medienurteil ist für einen bereitgestellten Modellvergleich keine notwendige Vorleistung.',essential_de='Gemeinwohlökonomie bezeichnet eine zu prüfende Konzeption; deren Befürworter betonen soziale/ökologische Kriterien. Das bedeutet nicht automatisch Zentralplanung oder Abschaffung privaten Eigentums. Der Vergleich muss die tatsächlich bereitgestellte Variante von bestehenden Regeln Sozialer Marktwirtschaft und von freiwilligen Unternehmensberichten unterscheiden.',essential_en='Economy for the Common Good is a proposal to examine; its proponents emphasise social/environmental criteria. This does not automatically mean central planning or abolition of private ownership. A comparison must distinguish the supplied version from existing social-market rules and voluntary company reports.',performance_de='Die Person erstellt einen begründeten Vergleich nach drei Kriterien, kennzeichnet Befürworteraussage und hypothetische Modellregel und unterscheidet Unternehmensinstrument und gesamtwirtschaftlichen Ordnungsrahmen.',performance_en='The learner makes a reasoned comparison across three criteria, labels proponents’ claims and hypothetical model rules and distinguishes a company-level tool from an economy-wide framework.',archetype='concept',axes=[('rule-scope','Modellvorschlag für den Ordnungsrahmen gegenüber freiwilligem Unternehmensbericht.','An economy-wide framework proposal versus a voluntary company report.'),('comparison-criteria','Ziele, Eigentum und marktliche Koordination.','Objectives, property and market coordination.')],cases=[case('supplied-common-good-variant','Vergleiche zwei bereitgestellte didaktische Modellbeschreibungen. Soziale Marktwirtschaft: private Unternehmen, Preis-/Wettbewerbskoordination, staatlicher Ordnungsrahmen und sozialer Ausgleich. Hypothetische GWÖ-Variante: private Unternehmen und Marktpreise bleiben; transparente soziale/ökologische Bilanzkriterien sollen zusätzlich staatliche Beschaffungsanreize beeinflussen. Diese Variante ist ein Unterrichtsvorschlag, keine Aussage über geltende allgemeine Gesetzespflicht. Vergleiche Ziele, Eigentum und Koordination.','Compare two supplied teaching-model descriptions. Social market economy: private firms, price/competition coordination, a state framework and social support. Hypothetical common-good variant: private firms and market prices remain; transparent social/environmental reporting criteria are proposed to influence procurement incentives. This is a classroom proposal, not a claim of a general current legal duty. Compare objectives, property and coordination.','Beide Beschreibungen erhalten Privateigentum und Marktkoordination; die Variante ergänzt konkret beschriebene Anreize und Gewichtung sozialer/ökologischer Zielkriterien. GWÖ wird nicht wegen ihres Namens zur Zentralplanung gemacht; auch die Soziale Marktwirtschaft hat soziale Ziele. Wirkung hängt von Kriterien, Umsetzung und Anreizen ab.','Both descriptions retain private ownership and market coordination; the variant adds specified incentives and emphasis on social/environmental criteria. The label does not turn it into central planning, and the social market economy also has social objectives. Effects depend on criteria, implementation and incentives.','Drei Ordnungsdimensionen anhand tatsächlicher Regeln statt Etiketten vergleichen.','Compare three dimensions using actual described rules rather than labels.'),case('voluntary-report-not-new-national-order','Ein zweites fiktives Unternehmen veröffentlicht freiwillig eine Gemeinwohlbilanz zusätzlich zur Finanzrechnung. Eigentum, Wettbewerb, gesetzliche Steuern und Sozialregeln bleiben unverändert. Eine Schlagzeile behauptet, dadurch sei das Land bereits vollständig in eine neue Wirtschaftsordnung überführt. Prüfe anhand derselben Vergleichskriterien, welche Aussage das Material wirklich trägt.','A second fictional company voluntarily publishes a common-good report alongside financial accounts. Ownership, competition, statutory taxes and social rules remain unchanged. A headline claims this has transformed the whole country into a new economic order. Use the same comparison criteria to assess what the material supports.','Das Material belegt ein zusätzliches betriebliches Bewertungs-/Transparenzinstrument und eine Zielgewichtung. Es belegt keine Änderung des nationalen Eigentums- oder Koordinationssystems und keine allgemeine GWÖ-Rechtsordnung. Instrument und Ordnungsrahmen werden getrennt, ohne das Instrument pauschal wirkungslos zu nennen.','The material establishes an additional company evaluation/transparency tool and emphasis on objectives. It establishes neither national property/coordination changes nor a general common-good legal order. The tool is distinguished from the framework without declaring it universally ineffective.','Unternehmensebene und Wirtschaftsordnung im frischen Grenzfall trennen.','Separate a company-level tool from an economic order in a fresh boundary case.')]),
dict(prefix='772b6d9f',title='Gerichtszweige anhand von Zuständigkeitsregeln unterscheiden',title_en='Distinguish court branches using jurisdiction rules',description='Die lernende Person kann vorgegebene Rechtsstreitigkeiten anhand bereitgestellter Zuständigkeitsregeln der ordentlichen, Arbeits-, Verwaltungs-, Sozial- oder Finanzgerichtsbarkeit zuordnen und die Zuordnung begründen.',description_en='The learner can assign supplied disputes to ordinary, labour, administrative, social or fiscal courts using provided jurisdiction rules and justify the assignment.',requires=['dae93971-726c-56e5-8044-19dbd40febf7'],section='WR11 7.2',content='Aufbau der Gerichtsbarkeit',year=11,boundary='Abgegrenzte Fünf-Gerichtszweig-Zuordnung; keine vollständige Instanzen-, Rechtsmittel- oder Verfassungsgerichtsbarkeitskompetenz.',prereq_reason='Normmerkmale auf den vorgegebenen Streit anwenden ist nötig. Ein fertiges Urteil über sämtliche Rechtsstaatsfunktionen oder die Eigentumsordnung ist für diese Zuordnung keine notwendige Vorleistung.',essential_de='Gerichtszweige unterscheiden sich nach gesetzlicher Zuständigkeit, nicht nach dem Wort Staat oder Geld im Fall. Spezialzuweisungen begrenzen allgemeine Regeln. Ein Steuerbescheid gehört unter den bereitgestellten Bedingungen zur Finanzgerichtsbarkeit, ein Steuerstrafverfahren nicht.',essential_en='Court branches follow statutory jurisdiction rather than whether a case mentions government or money. Specific statutory assignments limit general rules. Under the supplied conditions a tax assessment belongs to fiscal courts, but a tax-related criminal case does not.',performance_de='Die Person nutzt bereitgestellte aktuelle Kriterien, bestimmt den maßgeblichen Streitgegenstand und begründet alle fünf Grundzuordnungen samt einem Abgrenzungsfall.',performance_en='The learner uses supplied current criteria, identifies the subject of each dispute and explains all five basic classifications and a boundary case.',archetype='procedure',axes=[('dispute-object','Privater Anspruch, öffentliche Regel und besondere Leistungs-/Abgabenstreitigkeit.','A private claim, public rule and specialised benefits/tax disputes.'),('special-assignment','Spezielle Zuständigkeit und Ausschluss von Steuerstrafverfahren.','Specific jurisdiction and exclusion of tax criminal proceedings.')],cases=[case('civil-admin-social','Ordne drei fiktive Streitigkeiten anhand bereitgestellter datierter §13GVG,§40VwGO und§51SGG zu: unbezahlte Rechnung aus privatem Warenkauf, Streit über einen behördlichen Baubescheid ohne Sonderzuweisung, gesetzlicher Rentenversicherungs-Leistungsanspruch. Begründe mit Streitgegenstand und Regel; Verfassungs- und Rechtsmittelverfahren sind ausgenommen.','Assign three fictional disputes using supplied dated GVGsection13, VwGOsection40 and SGGsection51: an unpaid private sales invoice, an administrative building decision with no special allocation and a statutory pension-insurance benefit claim. Explain through the subject and rule; constitutional/appeal proceedings are excluded.','Privater Warenkauf: ordentliche Gerichtsbarkeit; nichtverfassungsrechtlicher Baubescheid ohne Sonderzuweisung: Verwaltungsgerichtsbarkeit; gesetzliche Rentenleistung: Sozialgerichtsbarkeit. Ein staatlicher Leistungsträger führt nicht automatisch immer zum Verwaltungsgericht.','Private sale: ordinary courts; a non-constitutional administrative building decision without special allocation: administrative courts; statutory pension benefits: social courts. A state institution does not automatically imply administrative jurisdiction.','Drei unterschiedliche Streitgegenstände statt bloßer Akteursnamen.','Three different dispute subjects rather than labels for actors.'),case('labour-fiscal-criminal-boundary','Ordne anhand bereitgestellter datierter §2ArbGG,§33FGO und§13GVG zu: ausstehender Lohn aus einem Arbeitsvertrag; anfechtbarer Einkommensteuerbescheid im beschriebenen Abgabenstreit; Strafverfahren wegen des Verdachts einer Steuerstraftat. Der Verdacht ist unbewiesen. Begründe insbesondere, weshalb das Wort Steuer nicht alle Fälle der Finanzgerichtsbarkeit zuweist.','Assign cases using supplied dated ArbGGsection2, FGOsection33 and GVGsection13: unpaid contractual wages, a challenged income-tax assessment in the specified tax dispute and criminal proceedings concerning a suspected tax offence. The suspicion is unproven. Explain especially why the word tax does not place every case in fiscal courts.','Lohn: Arbeitsgerichtsbarkeit; Steuerbescheid: Finanzgerichtsbarkeit im gegebenen Anwendungsbereich; Steuerstrafsache: ordentliche Strafgerichtsbarkeit, da §33(3)FGO Straf-/Bußgeldverfahren ausschließt. Die Zuständigkeitszuordnung ist keine Verurteilung oder abschließende Prüfung des Anspruchs.','Wages: labour courts; the assessment: fiscal courts within the stated scope; a tax criminal case: ordinary criminal courts because FGOsection33(3) excludes criminal/administrative-offence proceedings. Classification is neither conviction nor final adjudication of the claim.','Spezialzuweisung und echter Gegenfall zur Schlagwortzuordnung.','Specific allocation and a genuine counterexample to keyword classification.')]),
dict(prefix='575c08d4',title='Handelsmuster mit der Faktorproportionentheorie erklären',title_en='Explain trade patterns using factor-proportions theory',description='Die lernende Person kann anhand vorgegebener relativer Faktorausstattungen und Güterintensitäten ein Handelsmuster mit der Faktorproportionentheorie erklären und die Aussage an deren Modellannahmen binden.',description_en='The learner can explain a trade pattern from supplied relative factor endowments and goods’ factor intensities using factor-proportions theory and limit the conclusion to the model’s assumptions.',requires=[],section='WR11 7.3',content='weitere Handelstheorien, z. B. Faktorproportionentheorie, Produktlebenszyklustheorie',year=11,boundary='Ein begrenztes Heckscher-Ohlin-Modell mit relativen Faktoren; keine Pflicht zu allen weiteren Handelstheorien oder vollständiger realer Länderprognose.',prereq_reason='Medienurteile und Wechselkursbetroffenheit sind für ein vollständig bereitgestelltes Zwei-Faktor-Handelsmodell keine universellen Vorleistungen. Es gibt hier keinen zusätzlich vorausgesetzten dedizierten Faktorproportionen-Vorgänger; das Material liefert Definition, Verhältnisse und Modellbedingungen.',essential_de='Relative Ausstattung bedeutet das Verhältnis von Kapital zu Arbeit, nicht die absolute Kapitalmenge. Unter den angegebenen Heckscher-Ohlin-Bedingungen exportiert das relativ kapitalreiche Land das relativ kapitalintensive Gut. Unterschiedliche Technologien oder verletzte Annahmen erlauben nicht dieselbe sichere Schlussfolgerung.',essential_en='Relative endowment means the ratio of capital to labour, not the absolute amount of capital. Under the stated Heckscher-Ohlin conditions, the relatively capital-abundant country exports the relatively capital-intensive good. Different technologies or violated assumptions do not justify the same definite conclusion.',performance_de='Die Person berechnet oder vergleicht Kapital-Arbeits-Verhältnisse, verbindet relative Ausstattung und Güterintensität zur bedingten Modellvorhersage und prüft einen veränderten Annahmenfall.',performance_en='The learner calculates or compares capital–labour ratios, connects relative endowment and goods’ intensities to a conditional model prediction and checks a changed-assumption case.',archetype='modeling',axes=[('relative-vs-absolute','Kapital-Arbeits-Verhältnis trotz anderer absoluter Größen.','Capital–labour ratios despite different absolute amounts.'),('model-assumptions','Gleiche Technologien und Intensitätsordnung gegenüber verletzt gewordener Annahme.','Common technologies and factor-intensity ordering versus a violated assumption.')],cases=[case('two-country-endowment','Ein vollständig vorgegebenes Zwei-Länder-Modell hat A:100Kapitaleinheiten/50Arbeitseinheiten und B:60/120. X ist bei gemeinsamen Faktorpreisen relativ kapitalintensiv, Y relativ arbeitsintensiv; die Intensitätsordnung kehrt sich nicht um. Gemeinsame Technologie, Wettbewerb, gleiche homothetische Präferenzen, Handel beider Güter, Faktorenmobilität innerhalb eines Landes und Immobilität zwischen Ländern sind Annahmen. Erläutere nach der bereitgestellten Faktorproportionentheorie das bedingte Exportmuster.','A fully supplied two-country model has A:100capital units/50labour units and B:60/120. X is relatively capital-intensive and Y labour-intensive at common factor prices, with no factor-intensity reversal. Common technology, competition, identical homothetic preferences, trade in both goods, domestic factor mobility and international factor immobility are assumptions. Use the supplied factor-proportions theory to explain the conditional export pattern.','A hatK/L=2,B=0,5;A ist relativ kapitalreich und exportiert unter dem Modell X,B entsprechendY. Es geht um relative Ausstattung, nicht die Größenordnung allein. Diese Vorhersage beweist kein reales unveränderliches Exportmuster aller Länder.','A hasK/L=2 and B=0.5; A is relatively capital-abundant and exportsX in the model, while B exportsY. Relative endowment rather than scale alone matters. The prediction establishes no permanent real-world trade pattern for every country.','Relative Faktoren und Güterintensitäten zur ausdrücklich bedingten Erklärung verbinden.','Connect relative factors and goods’ intensities in an explicitly conditional explanation.'),case('less-capital-more-capital-abundant','Ein neuer Modellfall hat A:100Kapital/200Arbeit und B:60Kapital/30Arbeit. Zunächst gelten dieselben Annahmen und Güterintensitäten. Prüfe die Behauptung, A müsse wegen mehr absolutem Kapital das kapitalintensive Gut exportieren. Danach setzt das Material unterschiedliche Technologien voraus, deren Faktorbedarf nicht angegeben ist; begrenze nun die Aussage.','A fresh case has A:100capital/200labour and B:60capital/30labour, initially with the same assumptions and intensities. Assess the claim that A must export the capital-intensive good because it has more capital in absolute terms. Then the material introduces different technologies with unspecified factor requirements; limit the conclusion.','A hat0,5,B2: B ist trotz weniger absolutem Kapital relativ kapitalreich, daher unter Ausgangsannahmen ExportX. Mit unbekannten unterschiedlichen Technologien trägt diese einfache Ableitung nicht mehr allein; weitere Kosten-/Intensitätsdaten sind nötig.','A has0.5 and B2: B is relatively capital-abundant despite less absolute capital, so exportsX under the initial assumptions. With unspecified different technologies, that simple inference no longer suffices; additional cost/intensity information is needed.','Echter relativer Gegenfall und neue Modellgrenze statt nur neuer Zahlen.','A genuine relative counterexample and new model limit rather than changed numbers alone.')]),
dict(prefix='7a2435f2',title='Portfoliorendite und Diversifikationsgrenzen erklären',title_en='Explain portfolio returns and the limits of diversification',description='Die lernende Person kann für vorgegebene Portfolios gewichtete Renditen berechnen und anhand unterschiedlicher gemeinsamer Kursverläufe Möglichkeiten und Grenzen der Diversifikation erklären.',description_en='The learner can calculate weighted returns for supplied portfolios and use differing joint price movements to explain the possibilities and limits of diversification.',requires=['047ce369-b605-5cc6-8363-c5d288f5e938'],section='WR11 7.4',content='Portfoliotheorie und Diversifikation',year=11,boundary='Gewichtete Szenariorendite und Zusammenhang der Einzelanlagen; keine persönliche Empfehlung, optimale Portfolio- oder vollständige Varianzrechnung.',prereq_reason='Die beibehaltene Anlagekriterienkompetenz trägt Rendite/Risiko-Abgrenzung. Geldmarktakteursanalyse ist kein notwendiger Zwischenschritt der gegebenen Portfoliofälle.',essential_de='Portfoliorendite ist die mit den Anfangsanteilen gewichtete Rendite der Anlagen. Diversifikation kann einzelne Risiken abmildern, abhängig von gemeinsamen Bewegungen; bei gleichgerichteten Verlusten schützt bloße Anzahl nicht. Die gegebenen Szenarien sind keine Prognose oder Anlageempfehlung.',essential_en='Portfolio return is the return of each investment weighted by its initial share. Diversification may reduce individual risks depending on joint movements; merely adding investments does not protect against losses moving together. Supplied scenarios are neither forecasts nor investment recommendations.',performance_de='Die Person rechnet mit vorgegebenen Gewichten, vergleicht Gesamt- und Einzelverläufe und begründet eine Diversifikationswirkung oder deren Grenze bei geänderter gemeinsamer Bewegung.',performance_en='The learner calculates using supplied weights, compares portfolio and individual outcomes and explains a diversification effect or limitation when joint movements change.',archetype='modeling',axes=[('co-movement','Gegensätzliche gegenüber gleichgerichteten Verlusten.','Offsetting movements versus losses in the same direction.'),('risk-claim','Modellergebnis unter Szenarien gegenüber allgemeiner Gewinn-/Sicherheitsgarantie.','Scenario results versus a general profit/safety guarantee.')],cases=[case('offsetting-scenarios','Ein fiktives Portfolio enthält zu Periodenbeginn je50% A undB. In Szenario1: A+20%,B−10%; in Szenario2: A−10%,B+20%. Rechne die Portfoliorendite ohne Gebühren/Rebalancing und erläutere die Wirkung relativ zu Einzelanlagen. Die zwei Szenarien sind keine vollständige Wahrscheinlichkeitsverteilung.','A fictional portfolio initially holds50% each of A andB. Scenario1:A+20%,B−10%; scenario2:A−10%,B+20%. Calculate portfolio returns without fees/rebalancing and explain the effect relative to individual investments. The two scenarios are not a complete probability distribution.','Jeweils0,5×20%+0,5×(−10%)=+5%. Gegensätzliche Bewegungen glätten diese vorgegebenen Ergebnisse, beweisen aber weder risikofreie Anlage noch +5% in allen möglichen Zuständen.','In each scenario,0.5×20%+0.5×(−10%)=+5%. Offsetting movements smooth these supplied results but prove neither a risk-free investment nor+5% in every possible state.','Gewichtete Rechnung und Grenze der Szenariobehauptung.','Weighted calculation and limits of scenario claims.'),case('shared-loss-scenarios','Ein anderes Portfolio hat dieselben Anfangsgewichte: Szenario1 A+20%,B+10%; Szenario2 A−10%,B−20%. Berechne und prüfe die Behauptung, zwei Anlagen verhinderten jeden Verlust. Erläutere, welche gemeinsame Bewegung die Schlussfolgerung verändert.','Another portfolio has the same initial weights:scenario1 A+20%,B+10%;scenario2 A−10%,B−20%. Calculate and assess the claim that two investments prevent any loss. Explain which joint movement changes the conclusion.','Portfolio+15% beziehungsweise−15%. Beide Anlagen fallen gemeinsam im zweiten Zustand, daher keine Verlustgarantie durch Anzahl. Diversifikation betrifft Risikozusammenhang; unbekannte Wahrscheinlichkeiten erlauben keine vollständige Erwartungs-/Risikoprognose.','The portfolio yields+15% or−15%. Both assets fall together in the second state, so their number guarantees no protection. Diversification concerns the risk relationship; unknown probabilities permit no complete expected-return/risk forecast.','Geänderte gemeinsame Anreiz-/Risikostruktur statt bloßer Zahlentausch.','A changed joint-risk structure rather than numbers alone.')]),
dict(prefix='5a72a72a',title='Spieltheoretische Modellvorhersagen mit Versuchsdaten vergleichen',title_en='Compare game-theoretic predictions with experimental data',description='Die lernende Person kann für ein vorgegebenes spieltheoretisches Modell bedingte Handlungsvorhersagen ableiten, diese mit bereitgestellten Versuchsdaten vergleichen und Abweichungen unter Beachtung der Modell- und Versuchsbedingungen einordnen.',description_en='The learner can derive conditional action predictions from a supplied game-theory model, compare them with provided experimental data and interpret differences using the model and experimental conditions.',requires=['becf0989-ee9f-5c8e-8173-5b8246e7944a'],section='WR11 7.5',content='spieltheoretische Experimente, z. B. Ultimatum-Spiel, Allmendeproblem, Gefangenendilemma, Repeated Games',year=11,boundary='Modell-/Datenvergleich in einem Spiel; keine vollständige Experimentalplanung, Kausaldiagnose einzelner Motive oder Quotenpflicht echten Lernendenverhaltens.',prereq_reason='Grundmodell und Antwortanalyse bleiben notwendig. Die bisher direkte institutionenökonomische Voraussetzung bleibt bereits transitiv über becf erhalten; nur die redundante direkte Kante entfällt.',essential_de='Eine Spielmodellvorhersage gilt unter bestimmten Auszahlungs-, Informations-, Wiederholungs- und Verhaltensannahmen. Abweichende beobachtete Entscheidungen können mehrere Erklärungen haben. Versuchsdaten beweisen nicht automatisch einen bestimmten psychologischen Mechanismus, und Wiederholung verändert das strategische Modell.',essential_en='A game-model prediction holds under assumptions about payoffs, information, repetition and behaviour. Different observed choices may have several explanations. Experimental data do not automatically prove a specific psychological mechanism, and repetition changes the strategic model.',performance_de='Die Person leitet beste Antworten und Gleichgewicht aus den gegebenen Auszahlungen ab, vergleicht die bedingte Vorhersage mit Daten und erklärt Annahmen- oder Designänderungen als Grenzen der Interpretation.',performance_en='The learner derives best responses and equilibrium from supplied payoffs, compares the conditional prediction with data and explains assumption/design changes as limits on interpretation.',archetype='experiment',axes=[('repetition','Einmalige anonymisierte Entscheidung gegenüber wiederholter Interaktion.','An anonymous one-shot decision versus repeated interaction.'),('inference','Abweichung beschreiben gegenüber Motive oder Kausalmechanismus beweisen.','Describing differences versus proving motives or a causal mechanism.')],cases=[case('one-shot-dilemma-data','Ein fiktives einmaliges Spiel hat CC=(3,3),CD=(0,5),DC=(5,0),DD=(1,1),jeweils Spieler1/2; die bereitgestellte Standardannahme maximiert eigenen Punktnutzen. Von20 individuellen Entscheidungen wählen8 C. Bestimme die Modellvorhersage, berechne den beobachteten C-Anteil und prüfe die Behauptung, die Daten bewiesen eindeutig Altruismus.','A fictional one-shot game has CC=(3,3),CD=(0,5),DC=(5,0),DD=(1,1),ordered player1/2; the supplied standard assumption maximises one’s own point payoff. Of20 individual decisions,8choose C. Determine the model prediction, calculate the observed C share and assess whether this definitively proves altruism.','D ist strikt dominant,DD Nash unter der gegebenen Annahme;8/20=40% C widersprechen der reinen Alle-D-Vorhersage. Andere Präferenzen, Verständnis, Erwartungen oder Versuchsbedingungen können relevant sein; aus der Häufigkeit allein folgt kein eindeutiger Motivnachweis.','D is strictly dominant and DD Nash under the assumption;8/20=40%C differ from an all-D prediction. Different preferences, understanding, expectations or experimental conditions may matter; the frequency alone does not identify a unique motive.','Bedingte Modelllösung und empirische Abweichung ohne psychologischen Automatismus.','A conditional model solution and empirical difference without a psychological automatic inference.'),case('repeated-interaction-comparison','Ein zweiter fiktiver Versuch nutzt dieselben Runden-Auszahlungen, aber feste Partner, beobachtbare frühere Entscheidungen und unsichere weitere Runden. Der C-Anteil beträgt60%,im einmaligen Vergleich40%; Zufallszuweisung und sonstige Gleichheit sind nicht belegt. Vergleiche Vorhersage und Befund und begrenze einen behaupteten Wiederholungseffekt.','A second fictional experiment uses the same stage payoffs but fixed partners, observable previous choices and an uncertain continuation. The C share is60%,versus40% in a one-shot comparison; random assignment and other equivalence are unproven. Compare prediction and evidence and limit a claimed repetition effect.','Die Differenz beträgt20Prozentpunkte, nicht20% relativen Zuwachs. Zukunftsreaktionen können Kooperation bedingt beeinflussen, doch das einmalige Spielmodell lässt sich nicht unverändert übertragen. Ohne Kontroll-/Zuweisungsevidenz beweisen die60% weder alleinige Kausalität noch sichere Kooperation.','The difference is20percentage points, not a20% relative increase. Future responses may influence cooperation conditionally, but the one-shot model cannot be transferred unchanged. Without control/assignment evidence,60% proves neither sole causation nor guaranteed cooperation.','Frische Wiederholungsstruktur und beschränkte Kausalevidenz.','A fresh repeated-game structure and limited causal evidence.')]),
dict(prefix='055ef95c',title='Statische Rohstoffreichweiten berechnen und einordnen',title_en='Calculate and interpret static resource-reserve lifetimes',description='Die lernende Person kann anhand vorgegebener Reserven und jährlicher Förderung eine statische Rohstoffreichweite berechnen und erläutern, weshalb sie keine feste Vorhersage der Erschöpfung ist.',description_en='The learner can calculate a static reserve-to-production lifetime from supplied reserves and annual production and explain why it is not a fixed prediction of exhaustion.',requires=[],section='WR11 7.6',content='Vertiefung der Thematik an ausgewählten Beispielen globaler Zukunftstrends, z. B. Ressourcenknappheit',year=11,boundary='Eine definierte Reserven-/Förderquotientenleistung mit Modellgrenze; keine Vollprognose aller Rohstoffe oder zwingende ganze Zukunftsszenarioentwicklung.',prereq_reason='Die vorgegebene Formel, Einheiten und datierten Bestandsdefinitionen reichen für die begrenzte Leistung. Ein vollständiges aktuelles Wirtschafts-/Rechtsurteil und ganze Zukunftsszenarien sind keine universellen Vorleistungen.',essential_de='Statische Reichweite teilt definierte Reserven durch jährliche Förderung und hält beide Größen rechnerisch konstant. Reserven hängen auch von Wirtschaftlichkeit, Technik und Klassifikation ab; zukünftige Förderung kann sich ändern. Eine größere geologische Ressourcenkategorie ist nicht ohne Definition sofort abbaubare Reserve. Der Quotient ist kein Erschöpfungsdatum.',essential_en='Static lifetime divides defined reserves by annual production while treating both as constant. Reserves also depend on economics, technology and classification, and future production may change. A broader geological resource category is not automatically immediately recoverable reserves. The quotient is not an exhaustion date.',performance_de='Die Person verwendet richtige Bestands-/Flusseinheiten, berechnet den Quotienten und erklärt an veränderten Reserven-/Förderdaten die bedingte Aussage sowie erforderliche Kategoriengrenzen.',performance_en='The learner uses correct stock/flow units, calculates the ratio and explains its conditional meaning and category boundaries when reserves/production change.',archetype='modeling',axes=[('stocks-and-flows','Definierte Reserven in Tonnen gegenüber Förderung in Tonnen pro Jahr.','Defined reserves in tonnes versus production in tonnes per year.'),('dynamic-classification','Reklassifizierung und geänderte Förderung gegenüber fixem Erschöpfungsdatum.','Reclassification and changed production versus a fixed exhaustion date.')],cases=[case('static-thirty-years','Eine fiktive datierte Tabelle definiert wirtschaftlich gewinnbare Reserven mit120Mio.t und aktuelle jährliche Förderung4Mio.t/Jahr. Die bereitgestellte Formel lautet Reserven/jährliche Förderung. Berechne die statische Reichweite und prüfe die Behauptung, der Rohstoff sei sicher genau30Jahre später erschöpft. Erläutere mindestens zwei veränderliche Bedingungen.','A fictional dated table defines economically recoverable reserves as120million tonnes and current annual production as4million tonnes/year. The supplied formula is reserves/annual production. Calculate static lifetime and assess the claim that the material will certainly be exhausted exactly30years later. Explain at least two variable conditions.','120/4=30Jahre bei rechnerisch konstanten Größen. Nachfrage/Förderung, wirtschaftliche Abbaubarkeit, Technik oder neue Funde/Klassifikation können den Quotienten ändern. Die Rechnung belegt kein festes physisches Erschöpfungsdatum oder aktuellen echten Rohstoffbestand.','120/4=30years with constant quantities in the calculation. Demand/production, economic recoverability, technology or discoveries/classification can change the ratio. The calculation proves neither a fixed physical exhaustion date nor a real current resource stock.','Bestands-/Flussquotient und dynamische Modellgrenze.','A stock/flow ratio and a dynamic model limitation.'),case('reclassification-and-production-change','Eine neue fiktive Tabelle zeigt: Nach Förderung verbleiben112Mio.t bisherige Reserven; veränderte Technik macht weitere48Mio.t zur Reserve. Jahresförderung steigt auf8Mio.t/Jahr. Eine getrennt definierte zusätzliche Ressourcenkategorie von88Mio.t ist nicht als wirtschaftlich gewinnbare Reserve erfasst. Berechne die neue statische Reichweite und prüfe, ob eine kürzere Reichweite allein einen gesunkenen gesamten geologischen Bestand beweist.','A fresh fictional table shows112million tonnes remaining from previous reserves after production; changed technology adds48million tonnes to reserves. Annual production rises to8million tonnes/year. A separately defined additional resource category of88million tonnes is not economically recoverable reserves. Calculate the new static lifetime and assess whether a shorter lifetime alone proves a lower total geological stock.','Definierte Reserve112+48=160Mio.t;160/8=20Jahre. Reserve ist hier gestiegen, Förderrate stärker; die kürzere statische Reichweite beweist daher keine allgemeine Verknappung des geologischen Gesamtbestands. Die88Mio.t dürfen ohne geänderte Klassifikation nicht im Reservenzähler mitgerechnet werden.','Defined reserves are112+48=160million tonnes;160/8=20years. Reserves have risen while production has risen more, so the shorter ratio does not prove a general fall in total geological stock. The88million tonnes cannot be added to the reserve numerator without changed classification.','Reklassifizierung und Flussänderung verändern die Deutung trotz kürzerem Quotienten.','Reclassification and flow changes alter the interpretation despite a shorter ratio.')])
]

